scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions: pairs (i, j) where i < j but values[i] > values[j]
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.divide_and_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Divide each A_i by B_i (integer division) and sum
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

