{"name": "factorial_mod", "code": "import math

def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']
    # Calculate n! mod m
    factorial = math.factorial(n)
    result = factorial % mod
    return float(result)
"}

